#!/usr/bin/env bash
#
# Run the headless smoke test against the built plugin.
#
# Inputs (environment):
#   SMOKE_BIN    - compiled smoke_test binary (required)
#   META_FILE    - plugin-meta.txt generated by CMake (required)
#   INSTALL_DIR  - plugin install tree (required for the .so path)

set -euo pipefail

: "${SMOKE_BIN:?SMOKE_BIN is required}"
: "${META_FILE:?META_FILE is required}"
: "${INSTALL_DIR:?INSTALL_DIR is required}"

# shellcheck disable=SC1090
source "${META_FILE}"

PLUGIN_SO="$(find "${INSTALL_DIR}" -name "${PLUGIN_FILE}" -type f -print -quit)"
if [ -z "${PLUGIN_SO}" ]; then
	echo "error: ${PLUGIN_FILE} not found under ${INSTALL_DIR}" >&2
	exit 1
fi

DATA_DIR="$(find "${INSTALL_DIR}" -type d -path "*obs-plugins/${PLUGIN_TARGET}" -print -quit || true)"

echo "==> Loading ${PLUGIN_SO}, expecting version ${PLUGIN_VERSION}"
"${SMOKE_BIN}" "${PLUGIN_SO}" "${PLUGIN_VERSION}" "${DATA_DIR:-}"

echo "==> Smoke test passed"
